DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


def _is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _ordinal(s):
    y, m, d = map(int, s.split('-'))
    # Days in all complete years before year y (proleptic Gregorian).
    days = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    # Days in complete months of year y.
    days += sum(DAYS[: m - 1])
    # Leap day adjustment for the current year.
    if m > 2 and _is_leap(y):
        days += 1
    return days + d


def days_between(a, b):
    return _ordinal(b) - _ordinal(a)
